declare(strict_types=1);

namespace Acme\Data\Template;

abstract class CsvProcessor
{
    /**
     * Template method - final to enforce CSV processing skeleton.
     */
    final public function process(string $inputPath, string $outputPath): ProcessResult
    {
        $this->logProgress('Starting CSV processing');
        $handle = $this->openFile($inputPath);

        $headers = $this->parseHeaders($handle);
        $rows = $this->parseRows($handle, $headers);

        fclose($handle);
        $this->logProgress(sprintf('Parsed %d rows', count($rows)));

        $transformed = $this->transformData($rows);
        $this->logProgress('Data transformation complete');

        $outHandle = $this->writeOutput($outputPath, $transformed);
        fclose($outHandle);

        $this->logProgress('CSV processing completed');
        return ProcessResult::successful(count($transformed));
    }

    /**
     * Hook method - override for custom file opening.
     */
    protected function openFile(string $path)
    {
        $handle = fopen($path, 'r');
        if ($handle === false) {
            throw new \RuntimeException("Cannot open file: $path");
        }
        return $handle;
    }

    /**
     * Hook method for progress logging.
     */
    protected function logProgress(string $message): void
    {
        // Default: no-op
    }

    /**
     * Hook method for error handling.
     */
    protected function onError(string $message): void
    {
        throw new \RuntimeException($message);
    }

    /**
     * Hook method - override for custom file writing.
     */
    protected function writeOutput(string $path, array $data)
    {
        $handle = fopen($path, 'w');
        if ($handle === false) {
            throw new \RuntimeException("Cannot write file: $path");
        }
        foreach ($data as $row) {
            fputcsv($handle, $row);
        }
        return $handle;
    }

    abstract protected function parseHeaders($handle): array;
    abstract protected function parseRows($handle, array $headers): array;
    abstract protected function transformData(array $rows): array;
}

class UserImportProcessor extends CsvProcessor
{
    protected function parseHeaders($handle): array
    {
        $headers = fgetcsv($handle);
        return $headers ?: [];
    }

    protected function parseRows($handle, array $headers): array
    {
        $rows = [];
        while (($row = fgetcsv($handle)) !== false) {
            $rows[] = array_combine($headers, $row);
        }
        return $rows;
    }

    protected function transformData(array $rows): array
    {
        return array_map(function ($row) {
            $row['name'] = strtoupper($row['name'] ?? '');
            $row['created_at'] = date('Y-m-d');
            return $row;
        }, $rows);
    }
}

